`,d.jsx(t.h2,{children:"My role"}),`
`,d.jsx(t.p,{children:"As Campus Engagement Assistant at Student Affairs, I had full ownership of Orientation Week for 2025. That meant building the promotional strategy from scratch, coordinating logistics across multiple teams, and being on-site for the entire week to manage execution."}),`
`,d.jsx(t.h2,{children:"The promotional strategy"}),`
`,d.jsx(t.p,{children:"We ran campaigns across three channels: email to incoming students, Instagram, and physical signage across campus. The goal was not just reach but coherence. Every touchpoint needed to feel like it came from the same place and point toward the same thing: showing up."}),`
`,d.jsx(t.p,{children:"The hardest part was writing copy that felt warm and specific without being performative. Incoming students can tell when institutions are trying too hard to seem welcoming. The tone we settled on was more like a letter from someone who actually goes here."}),`
`,d.jsx(t.h2,{children:"What I learned"}),`
`,d.jsx(t.p,{children:"Running an event at this scale is mostly a logistics problem. But the interesting problems are the ones you cannot put in a spreadsheet. What do you do when the schedule shifts and 200 students are waiting with nowhere to go? How do you make a student who showed up alone feel like they made the right call?"}),`
`,d.jsx(t.p,{children:"The answer to both is the same: you design for the person, not the event. You think about what it feels like to be the person walking in, not what it looks like from the stage."})]})}function LT(e={}){const{wrapper:t}=e.components||{};return t?d.jsx(t,{...e,children:d.jsx(zf,{...e})}):zf(e)}function Bf(e){const t={h2:"h2",p:"p",...e.components};return d.jsxs(d.Fragment,{children:[d.jsx(t.p,{children:"The Impact Awards recognize students and staff at Dalhousie who have made meaningful contributions to campus life. It is the kind of event where the details matter because the people being honoured have earned something real."}),`
`,d.jsx(t.h2,{children:"My role"}),`
`,d.jsx(t.p,{children:"I managed end-to-end production for the 2025 ceremony. That included coordinating venue and catering, writing communications to nominees and guests, building the run-of-show, and being on-site to manage the day."}),`
`,d.jsx(t.h2,{children:"What made it different"}),`
`,d.jsx(t.p,{children:"Awards ceremonies can feel hollow if you are not careful. The format is predictable: speeches, applause, photographs. The challenge is to make the people being recognized actually feel recognized, not just processed through a program."}),`
`,d.jsx(t.p,{children:"The changes we made were small. Longer descriptions for each recipient. An opening that named what the awards were actually for. A room arrangement that let nominees sit with the people who nominated them."}),`
`,d.jsx(t.p,{children:"None of these were large. Together they shifted the energy of the room."}),`
`,d.jsx(t.h2,{children:"On producing events that matter"}),`
`,d.jsx(t.p,{children:"The thing I think about most from this event is the gap between what gets measured and what matters. We can count attendees and photograph the stage. We cannot easily measure whether someone felt genuinely seen."}),`
`,d.jsx(t.p,{children:"That gap is where the work is."})]})}function NT(e={}){const{wrapper:t}=e.components||{};return t?d.jsx(t,{...e,children:d.jsx(Bf,{...e})}):Bf(e)}function $f(e){const t={h2:"h2",p:"p",...e.components};return d.jsxs(d.Fragment,{children:[d.jsx(t.p,{children:"For two semesters as Marketing and PR Director at the Dalhousie Science Society, I led campaigns for more than four events per semester. The events ranged from casual social mixers to academic panels to the Society's annual formal."}),`
`,d.jsx(t.h2,{children:"The challenge"}),`
`,d.jsx(t.p,{children:'Student society events live and die by turnout. The students you want to reach are busy, bombarded with notifications, and mostly indifferent to generic "come join us" messaging.'}),`
`,d.jsx(t.p,{children:'The societies that break through are the ones that make specific promises. Not "a great evening" but "this particular thing, at this particular time, designed for someone like you."'}),`
`,d.jsx(t.h2,{children:"What we built"}),`
`,d.jsx(t.p,{children:"We redesigned the promotional approach from the ground up. Each event got a distinct visual identity that connected to the Society's overall brand but felt tailored to that event. Copy was written for the person most likely to actually come, not for the broadest possible audience."}),`
`,d.jsx(t.p,{children:"We also started using Instagram Stories more aggressively in the 48 hours before each event. A single well-timed story with the right energy could move real numbers."}),`
`,d.jsx(t.h2,{children:"Results"}),`
`,d.jsx(t.p,{children:"Over the two semesters, we consistently hit and exceeded turnout targets. More importantly, the events started to feel different. Students mentioned them to each other not just because they saw a post but because they expected them to be worth going to."}),`
`,d.jsx(t.p,{children:"That shift in expectation is harder to build than any single campaign."})]})}function MT(e={}){const{wrapper:t}=e.components||{};return t?d.jsx(t,{...e,children:d.jsx($f,{...e})}):$f(e)}function Uf(e){const t={h2:"h2",p:"p",...e.components};return d.jsxs(d.Fragment,{children:[d.jsx(t.p,{children:"Event Tree started from a frustration that I suspect many students share. There were things happening on campus every week. Most students did not know about them until it was too late, if at all."}),`
`,d.jsx(t.p,{children:"The information existed. It just did not travel."}),`
`,d.jsx(t.h2,{children:"The problem"}),`
`,d.jsx(t.p,{children:"Campus communication is fragmented by design. Each faculty, society, department, and team communicates independently, through their own channels, with their own audiences. A student following fifty accounts still misses most of what is happening."}),`
`,d.jsx(t.p,{children:"Event Tree was built to be the layer on top of all of that. One place where students could see what was happening across campus, organized in a way that made sense for how students actually use their phones."}),`
`,d.jsx(t.h2,{children:"Building it"}),`
`,d.jsx(t.p,{children:"I handled the concept, branding, UX design, and promotional strategy independently. The technical side required learning as I went. The harder part was the design problem: how do you make a discovery platform feel warm and human rather than like a search engine?"}),`
`,d.jsx(t.p,{children:"The answer I came to was curation. Not just aggregation but selection. Highlighting the events that deserved more attention than their organizers' Instagram following could give them."}),`
`,d.jsx(t.h2,{children:"What it means to me"}),`
`,d.jsx(t.p,{children:"Event Tree is the project I am most proud of, not because it is the most polished thing I have built, but because it started with a genuine problem and became a genuine attempt to solve it."}),`
